def scenario_count() -> int:
    return len(SCENARIOS)


def scenarios_for_method(method: str) -> List[Dict[str, Any]]:
    m = method.upper()
    return [s for s in SCENARIOS if s["method"] == m]


def scenarios_for_class(route_class: str) -> List[Dict[str, Any]]:
    return [s for s in SCENARIOS if s["route_class"] == route_class]


def sample_mutating(limit: int = 100) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    for s in SCENARIOS:
        if not s["expect_safe"]:
            out.append(s)
        if len(out) >= limit:
            break
    return out


